async function loadAll(ids) {
  const pending = ids.map((id) => fetchReport(id));   // every call starts now
  try {
    return await Promise.all(pending);                // collect later, order preserved
  } catch (err) {
    // the first rejection arrives here; the other calls keep running
    throw err;                                        // preserve the failure channel
  }
}

